### Python

```python
import sys


# 处理一组测试数据，返回最少操作次数和操作下标列表
def solve_one(n, s):
    stack = []          # 存未匹配的 '(' 的下标
    bad_right = []      # 存未匹配的 ')' 的下标

    for i, ch in enumerate(s, 1):  # 下标从 1 开始
        if ch == '(':
            stack.append(i)
        else:
            if stack:
                stack.pop()        # 匹配掉一对括号
            else:
                bad_right.append(i)

    bad_left = stack               # 剩下的全是未匹配的 '('

    a = len(bad_right)
    b = len(bad_left)

    ans = []

    # 翻转最前面的 ceil(a / 2) 个未匹配 ')'
    need_right = (a + 1) // 2
    for i in range(need_right):
        ans.append(bad_right[i])

    # 翻转最后面的 ceil(b / 2) 个未匹配 '('
    need_left = (b + 1) // 2
    for i in range(b - need_left, b):
        ans.append(bad_left[i])

    return len(ans), ans


def main():
    input = sys.stdin.readline
    t = int(input().strip())
    out = []

    for _ in range(t):
        n = int(input().strip())
        s = input().strip()

        k, ans = solve_one(n, s)
        out.append(str(k))
        if k == 0:
            out.append("")
        else:
            out.append(" ".join(map(str, ans)))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()
```

